  
-- ========== USER MANAGEMENT QUERIES ==========

-- 1. Register New User (registerUser)
INSERT INTO users (fullname, username, email, phone_number, user_type, max_borrow_limit, user_status, password, age)
VALUES (?, ?, ?, ?, ?, ?, 'Active', ?, ?);

-- 2. User Login (userLogin)
SELECT user_id, username, password, user_status 
FROM users 
WHERE username = ?;

-- 3. Get User Info (getUserInfo)
SELECT user_id, fullname, username, email, phone_number, user_type, max_borrow_limit, user_status, age
FROM users 
WHERE user_id = ?;

-- 4. Check if User Can Borrow (canUserBorrow)
SELECT u.user_status, u.max_borrow_limit, COUNT(bp.process_code) AS current_borrowings
FROM users u
LEFT JOIN borrowing_process bp ON u.user_id = bp.user_id AND bp.status IN ('Borrowed')
WHERE u.user_id = ?
GROUP BY u.user_id;

-- ========== STAFF MANAGEMENT QUERIES ==========

-- 5. Staff Login (staffLogin)
SELECT staff_id, username, password, staff_status, position
FROM staff_member 
WHERE username = ?;

-- 6. Get Staff Info (getStaffInfo)
SELECT staff_id, member_name, email, phone_num, position, hire_date, salary, staff_status, age
FROM staff_member 
WHERE staff_id = ?;

-- 7. Get Active Staff (getActiveStaff)
SELECT staff_id, member_name, email, position, hire_date, staff_status
FROM staff_member
WHERE staff_status = 'Active'
ORDER BY position, member_name;

-- ========== BOOKS MANAGEMENT QUERIES ==========

-- 8. Get Available Books (getAvailableBooks)
SELECT book_id, book_name, author_name, release_year, available_copies, book_description, book_language, total_pages
FROM book 
WHERE available_copies > 0 
ORDER BY book_name;

-- 9. Get All Books (getAllBooks)
SELECT book_id, book_name, author_name, release_year, available_copies, book_description, book_language, total_pages
FROM book 
ORDER BY book_name;

-- 10. Get Book By ID (getBookById)
SELECT * 
FROM book 
WHERE book_id = ?;

-- 11. Get Book Cover (getBookCover)
SELECT book_cover 
FROM book 
WHERE book_id = ?;

-- 12. Add New Book (addBook)
INSERT INTO book (book_name, author_name, release_year, available_copies, book_description, book_language, total_pages, book_cover)
VALUES (?, ?, ?, ?, ?, ?, ?, ?);

-- 13. Search Books (searchBooks)
SELECT book_id, book_name, author_name, release_year, available_copies, book_description, book_language
FROM book
WHERE book_name LIKE ? OR author_name LIKE ? OR book_description LIKE ?
ORDER BY book_name;

-- ========== BORROWING PROCESS QUERIES ==========

-- 14. Check Book Availability (isBookAvailable)
SELECT available_copies 
FROM book 
WHERE book_id = ?;

-- 15. Borrow Book - Insert Borrowing Record (borrowBook)
INSERT INTO borrowing_process ( process_code,user_id, book_id, staff_id, process_date, due_date, status)
VALUES ( ?,?, ?, ?, ?, ?, 'Borrowed');

-- 16. Borrow Book - Update Book Copies (borrowBook)
UPDATE book 
SET available_copies = available_copies - 1 
WHERE book_id = ?;

-- 17. Return Book - Get Borrowing Info (returnBook)
SELECT * 
FROM borrowing_process 
WHERE process_code = ?;

-- 18. Return Book - Update Borrowing Record (returnBook)
UPDATE borrowing_process
SET return_date = ?, status = 'Returned'
WHERE process_code = ?;

-- 19. Return Book - Increment Book Copies (returnBook)
UPDATE book 
SET available_copies = available_copies + 1 
WHERE book_id = ?;


-- 20. Get User Borrowings (getUserBorrowings)
SELECT bp.process_code, b.book_name, b.author_name, bp.process_date, bp.due_date, bp.return_date, bp.status,
       DATEDIFF(CURDATE(), bp.due_date) AS days_overdue
FROM borrowing_process bp
INNER JOIN book b ON bp.book_id = b.book_id
WHERE bp.user_id = ?
ORDER BY bp.process_date DESC;

-- ========== ADDITIONAL USEFUL QUERIES ==========

-- 21. Get Most Borrowed Books
SELECT b.book_id, b.book_name, b.author_name, COUNT(bp.process_code) AS times_borrowed
FROM book b
LEFT JOIN borrowing_process bp ON b.book_id = bp.book_id
GROUP BY b.book_id
ORDER BY times_borrowed DESC
LIMIT 10;

-- 22. Get User Activity Summary
SELECT u.user_id, u.fullname, u.user_type,
       COUNT(bp.process_code) AS total_borrowed,
       SUM(CASE WHEN bp.status = 'Borrowed' THEN 1 ELSE 0 END) AS currently_borrowed,
       SUM(CASE WHEN bp.status = 'Returned' THEN 1 ELSE 0 END) AS returned_books
FROM users u
LEFT JOIN borrowing_process bp ON u.user_id = bp.user_id
GROUP BY u.user_id
ORDER BY total_borrowed DESC;

